$b['Create a large tattoo in which several different metals appear to have been crafted by different civilizations and then assembled centuries later into one coherent artifact. Use steel bronze gold copper patina and engraved silver selectively'] = 'Two panels side by side on one image, divided down the middle. LEFT PANEL: the tattoo design alone on a plain white background, shown flat exactly as described, no body, drawn large so it fills most of the panel. RIGHT PANEL: Studio photograph of a real person''s body showing the same exact tattoo where described, healed tattoo on real skin in soft even light, the rest of the body modestly covered by simple plain clothing, only the tattooed area bare, plain seamless light grey studio backdrop - no room, no furniture, no scenery. The tattoo in both panels is identical. The tattoo: Create a large tattoo in which several different metals appear to have been crafted by different civilizations and then assembled centuries later into one coherent artifact. Use steel, bronze, gold, copper patina and engraved silver selectively. Archaeological, imaginative, world-class. In the right panel it is on a man, upper back. THE CATEGORY IS METALWORK. THE GOAL IS NOT TO MAKE OBJECTS SHINY. THE GOAL IS TO MAKE METAL FEEL PHYSICAL. THE VIEWER SHOULD ALMOST UNDERSTAND: HOW IT WAS FORGED. HOW IT WAS HAMMERED. HOW IT WAS ENGRAVED. HOW IT WAS ASSEMBLED. HOW IT AGED. HOW LIGHT MOVES ACROSS IT. Use the visual characteristics of the specific metal. STEEL: Cool, hard, sharp, powerful. BLACKENED STEEL: Dark, dramatic, industrial. DAMASCUS STEEL: Flowing layered patterns built into the material. COPPER: Warm, organic, capable of beautiful turquoise oxidation. BRONZE: Ancient, sculptural, archaeological. SILVER: Bright, elegant, ideal for engraving and precious detail. GOLD: Powerful as an accent. Do not cover everything in gold. TITANIUM: Modern, lightweight-looking, capable of extraordinary heat coloration. BRASS: Warm, mechanical, antique. Do not make every piece polished. Metal can be: Scratched Dented Ancient Dirty Weathered Burned Oxidized Hammered Brushed Cracked Polished Engraved MATERIAL HISTORY MAKES THE TATTOO INTERESTING'
$b['Create a completely original metalwork tattoo using a subject not normally associated with metal. Choose the metal or combination of metals based on the subject. Use forging sculpture engraving patina inlay wear and material transformation only where they strengthen the artwork. The final result should make an experienced tattoo artist stop and study how the illusion was constructed'] = 'Two panels side by side on one image, divided down the middle. LEFT PANEL: the tattoo design alone on a plain white background, shown flat exactly as described, no body, drawn large so it fills most of the panel. RIGHT PANEL: Studio photograph of a real person''s body showing the same exact tattoo where described, healed tattoo on real skin in soft even light, the rest of the body modestly covered by simple plain clothing, only the tattooed area bare, plain seamless light grey studio backdrop - no room, no furniture, no scenery. The tattoo in both panels is identical. The tattoo: Create a completely original metalwork tattoo using a subject not normally associated with metal. Choose the metal or combination of metals based on the subject. Use forging, sculpture, engraving, patina, inlay, wear and material transformation only where they strengthen the artwork. The final result should make an experienced tattoo artist stop and study how the illusion was constructed. Original, masterful, unforgettable. In the right panel it is on a person, on whichever body area makes the artwork strongest. THE CATEGORY IS METALWORK. THE GOAL IS NOT TO MAKE OBJECTS SHINY. THE GOAL IS TO MAKE METAL FEEL PHYSICAL. THE VIEWER SHOULD ALMOST UNDERSTAND: HOW IT WAS FORGED. HOW IT WAS HAMMERED. HOW IT WAS ENGRAVED. HOW IT WAS ASSEMBLED. HOW IT AGED. HOW LIGHT MOVES ACROSS IT. Use the visual characteristics of the specific metal. STEEL: Cool, hard, sharp, powerful. BLACKENED STEEL: Dark, dramatic, industrial. DAMASCUS STEEL: Flowing layered patterns built into the material. COPPER: Warm, organic, capable of beautiful turquoise oxidation. BRONZE: Ancient, sculptural, archaeological. SILVER: Bright, elegant, ideal for engraving and precious detail. GOLD: Powerful as an accent. Do not cover everything in gold. TITANIUM: Modern, lightweight-looking, capable of extraordinary heat coloration. BRASS: Warm, mechanical, antique. Do not make every piece polished. Metal can be: Scratched Dented Ancient Dirty Weathered Burned Oxidized Hammered Brushed Cracked Polished Engraved MATERIAL HISTORY MAKES THE TATTOO INTERESTING'
$mine = @(); foreach ($c in $cats.Keys) { $mine += @($cats[$c].Keys) }
$taken = @{}; $tt.specific.PSObject.Properties | ? { $mine -notcontains $_.Name } | % { $_.Value | ? { $_ } | % { $taken[(& $slug $_)] = 1 } }
$final = @{}
foreach ($c in $cats.Keys) {
  $kinds = @($cats[$c].Keys)
  $had = @($tt.subjects.$c | ? { $_ }); "  " + $c + " already has " + $had.Count + " sets - the new ones are ADDED, nothing removed"
  foreach ($k in $kinds) { if ($had -contains $k) { "  SET NAME ALREADY IN THIS CATEGORY: " + $k; $clash = $true } }
  if ($tt.subjects.PSObject.Properties[$c]) { $tt.subjects.$c = @($had + $kinds) } else { $tt.subjects | Add-Member -NotePropertyName $c -NotePropertyValue $kinds }
  foreach ($k in $kinds) {
    $names = @($cats[$c][$k] | % { $o = $_; if ($taken.ContainsKey((& $slug $o))) { $nn = $o + " in " + $c + " Style"; "  RENAMED: " + $nn | Out-Host } else { $nn = $o }; $final[$o] = $nn; $nn })
    if ($tt.specific.PSObject.Properties[$k]) { $tt.specific.$k = $names } else { $tt.specific | Add-Member -NotePropertyName $k -NotePropertyValue $names }
  }
}
$json = $tt | ConvertTo-Json -Depth 20 -Compress
$check = $json | ConvertFrom-Json
$afterCats = @($check.subjects.PSObject.Properties).Count
if ($clash -or $afterCats -lt $beforeCats -or $json.Length -lt ($got.raw.Length * 0.9)) { "  SAFETY STOP - the new catalog looks smaller than the old one, nothing written" } else {
$tmp = Join-Path $env:TEMP "card-tree-new.json"
[System.IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding $false))
npx wrangler kv key put --namespace-id $ns "card:tree" --path $tmp --remote 2>$null | Out-Null
"  catalog written in ONE save: " + $beforeCats + " categories before, " + $afterCats + " after"
"  saving the split-card settings and the tattoo descriptions..."
$n = 0
foreach ($c in $cats.Keys) { foreach ($k in $cats[$c].Keys) {
  $ks = & $slug $k
  RUN ("SETKV render:" + $ks + " The tattoo in both panels is identical.") | Out-Null
  RUN ("SETKV shape:" + $ks + " 3:2") | Out-Null
  RUN ("SETKV split:" + $ks + " yes") | Out-Null
  foreach ($o in $cats[$c][$k]) { RUN ("SETKV build:" + (& $slug $final[$o]) + " " + $b[$o]) | Out-Null; $n++ }
} }
"  " + $n + " descriptions saved - waiting 70 seconds so every server sees the new catalog..."
Start-Sleep -Seconds 70
$got2 = Read-Tree
$short = 0
foreach ($c in $cats.Keys) { foreach ($k in $cats[$c].Keys) { $h = @($got2.tree.specific.$k | ? { $_ }).Count; if ($h -ne $cats[$c][$k].Count) { "  STILL SHORT: " + $k + " has " + $h; $short++ } } }
if ($short) { "== " + $short + " sets short - send me this output ==" } else {
"== Metalwork saved - the test cards: =="
"== looking for old style words on Metalwork and its sets (exact names) =="
$want = @('context:metalwork-ancient-metals','context:metalwork-armor-and-body-architecture','context:metalwork-color-in-metal','context:metalwork-engraved-metal','context:metalwork-forged-creatures','context:metalwork-gold-silver-and-precious-metal','context:metalwork-impossible-metalwork','context:metalwork-industrial-metal','context:metalwork-masterpieces','context:metalwork-metal-botanicals')
$tmp = Join-Path $env:TEMP "aura-ctx-metalwork.json"
ConvertTo-Json @($want) | Set-Content -Path $tmp -Encoding utf8
$out = (npx wrangler kv bulk get $tmp --namespace-id $ns --remote 2>$null | Out-String)
$hits = [regex]::Matches($out, '"(context:[^"]+)":\s*"((?:[^"\\]|\\.)*)"')
if ($hits.Count -eq 0) { "  none found" } else { foreach ($h in $hits) { "  removed " + $h.Groups[1].Value + ": " + $h.Groups[2].Value; npx wrangler kv key delete --namespace-id $ns $h.Groups[1].Value --remote 2>$null | Out-Null }; "  waiting 70 seconds"; Start-Sleep -Seconds 70 }
foreach ($c in $cats.Keys) { RUN ("REDO " + $final[$test[$c]]) }
}
}
